// src/App.js
import React, { useState, useEffect } from "react";

const App = () => {
  const [timeLeft, setTimeLeft] = useState(10); // 84 hours in seconds
  const [surveyVisible, setSurveyVisible] = useState(false);
  const [formData, setFormData] = useState({
    q1: "",
    q2: "",
    q3: "",
    q4: "",
    q5: "",
    email: "",
  });

  useEffect(() => {
    if (timeLeft <= 0) return;
    const interval = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(interval);
  }, [timeLeft]);

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, "0")}:${minutes
      .toString()
      .padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({ ...prevData, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Survey Submitted:", formData);
    alert("Thank you for your feedback!");
    setFormData({
      q1: "",
      q2: "",
      q3: "",
      q4: "",
      q5: "",
      email: "",
    });
  };

  return (
    <div style={{ padding: "20px", textAlign: "center", backgroundColor: "#f9f9f9", minHeight: "100vh" }}>
      <h1 style={{ fontSize: "36px", color: "#6a0dad", marginBottom: "20px" }}>PlasmaPals</h1>
      <div style={{ maxWidth: "600px", margin: "0 auto", backgroundColor: "#fff", padding: "20px", borderRadius: "8px", boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)" }}>
        <p style={{ fontSize: "18px", marginBottom: "20px" }}>
          PlasmaPals is dedicated to educating people about the importance of plasma donation, its safety, and how you can make a difference.
        </p>
        <p style={{ fontSize: "24px", marginBottom: "20px" }}>Time until next survey: {formatTime(timeLeft)}</p>
        {timeLeft <= 0 && !surveyVisible && (
          <button
            onClick={() => setSurveyVisible(true)}
            style={{ backgroundColor: "#6a0dad", color: "#fff", padding: "10px 20px", border: "none", borderRadius: "5px", cursor: "pointer" }}
          >
            Take the Survey
          </button>
        )}
      </div>

      {surveyVisible && (
        <div style={{ maxWidth: "600px", margin: "20px auto", backgroundColor: "#fff", padding: "20px", borderRadius: "8px", boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)" }}>
          <h2 style={{ fontSize: "24px", marginBottom: "20px" }}>Weekly Update Survey</h2>
          <form onSubmit={handleSubmit}>
            {[
              "Was the time it took reasonable?",
              "Did you feel comfortable with the process?",
              "Did you feel that the staff was friendly and professional?",
              "Did you feel that you were properly compensated for your time?",
              "Were you satisfied with the overall experience?",
            ].map((question, index) => (
              <div key={index} style={{ marginBottom: "20px" }}>
                <p>{question}</p>
                <label>
                  <input
                    type="radio"
                    name={`q${index + 1}`}
                    value="true"
                    onChange={handleInputChange}
                    checked={formData[`q${index + 1}`] === "true"}
                    required
                  />
                  True
                </label>
                <label style={{ marginLeft: "20px" }}>
                  <input
                    type="radio"
                    name={`q${index + 1}`}
                    value="false"
                    onChange={handleInputChange}
                    checked={formData[`q${index + 1}`] === "false"}
                    required
                  />
                  False
                </label>
              </div>
            ))}

            <div style={{ marginBottom: "20px" }}>
              <label>
                Your Email:
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  style={{ display: "block", width: "100%", padding: "8px", marginTop: "5px", borderRadius: "5px", border: "1px solid #ccc" }}
                  required
                />
              </label>
            </div>

            <button
              type="submit"
              style={{ backgroundColor: "#28a745", color: "#fff", padding: "10px 20px", border: "none", borderRadius: "5px", cursor: "pointer" }}
            >
              Submit Survey
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

export default App;
